Method.Source:
/// <summary>
/// Adds controls to form state to build PO Put Away screen.
/// </summary>
/// <param name="_con">
/// Container containing the form state before the controls are added.
/// </param>
/// <param name="_licensePlateId">
/// The license plate id.
/// </param>
/// <param name="_extraText">
/// Label text.
/// </param>
/// <param name="_outputLocationRequiresLicensePlate">
/// A flag determining if the license plate control should be shown to the user; optional.
/// </param>
/// <returns>
/// Container containing the form state after the controls are added.
/// </returns>
/// <remarks>
/// AVA_007156_MDEReportFinish
/// </remarks>
container buildReportAsFinished(container           _con,
                                WHSLicensePlateId   _licensePlateId,
                                str                 _extraText,
                                boolean             _outputLocationRequiresLicensePlate)
{
    container ret;

    using (AVANoReportFinishedProposalQtyIDisposable instance = AVANoReportFinishedProposalQtyIDisposable::construct())
    {
        instance.noReportFinishedProposalQty = this.avaGetNoReportFinishedProposalQty();

        ret = next buildReportAsFinished(_con, _licensePlateId, _extraText, _outputLocationRequiresLicensePlate);

        ret = this.avaManageQtyError(ret);

    }

    return ret;
}

protected container avaManageQtyError(container _ret)
{
    container           ret = _ret;
    container           insertdisplayContainer;
    WHSRFMenuItemTable  menuItemTable;

    if (pass.exists(#MenuItem))
    {
        menuItemTable = WHSRFMenuItemTable::find(pass.lookupStr(#MenuItem));

        if (menuItemTable.AVAAllowReportFinishedQtyError == NoYes::Yes)
        {
            if (AVAWHSWorkExecuteDisplayHelper::existDisplayContainer(ret, #Name, #QTY))
            {
                if (!AVAWHSWorkExecuteDisplayHelper::existDisplayContainer(ret, #Name, #AVAQtyError))
                {
                    insertdisplayContainer = this.buildControl(#RFText, #AVAQtyError, "@SYS1032", 1, pass.lookupStr(#AVAQtyError), extendedTypeNum(ProdReportedError), '', 0);

                    ret = AVAWHSWorkExecuteDisplayHelper::insertDisplayContainer(ret, #Name, #QTY, insertdisplayContainer, 1);
                    ret = AVAWHSWorkExecuteDisplayHelper::removeDisplayContainer(ret, #Name, #QTY);
                }
            }
        }
    }

    return ret;
}

/// <summary>
/// Initializes an instance of the <c>WHSWorkCreateProdPut</c> class for creating the warehouse production put.
/// </summary>
/// <param name = "_productionDimensions">The dimensions for the production.</param>
/// <returns>The new <c>WHSWorkCreateProdPut</c> instance.</returns>
protected WHSWorkCreateProdPut initializeWHSWorkCreateProdPut(InventDim _productionDimensions)
{
    WHSWorkCreateProdPut avaWorkCreateProdPut;

    avaWorkCreateProdPut = next initializeWHSWorkCreateProdPut(_productionDimensions);

    avaWorkCreateProdPut.avaParmInventHandlingQty(WHSCatchWeightHelper::convertInventQuantity(pass.lookup(#ItemId),
                                                  pass.lookup(#UOM),
                                                  pass.lookupNum(#AVAQtyError),
                                                  _productionDimensions.inventDimId));


    return avaWorkCreateProdPut;
}

/// <summary>
///  Updates the mode and step based on the values from the pass.
/// </summary>
/// <param name = "_con">A container representing the UI.</param>
/// <param name = "_mode">The <c>WHSWorkExecuteMode</c> mode.</param>
/// <param name = "_step">The step.</param>
/// <param name = "_pass">The pass object.</param>
/// <returns>The updated container</returns>
public container updateModeStepPass(container           _con,
                                    WHSWorkExecuteMode  _mode,
                                    int                 _step,
                                    WHSRFPassthrough    _pass)
{
    container  avaRet;

    if (_step == 0
     && !_pass.exists(#Qty)
     && _pass.exists(#AVAQtyError))
    {
        _pass.remove(#AVAQtyError);

    }

    avaRet = next updateModeStepPass(_con, _mode, _step, _pass);

    return avaRet;
}

private AVANoReportFinishedProposalQty avaGetNoReportFinishedProposalQty()
{
    AVANoReportFinishedProposalQty  avaNoReportFinishedProposalQty;
    WHSRFMenuItemTable              avaMenuItemTable;

    avaMenuItemTable = WHSRFMenuItemTable::find(pass.lookupStr(#MenuItem));

    avaNoReportFinishedProposalQty = avaMenuItemTable.AVANoReportFinishedProposalQty;

    return avaNoReportFinishedProposalQty;
}
